mapper.select:
select
c1.C_Name as ecfContractorName, c2.C_Name as ecfSupervisorName, c3.C_Name as ecfApplyUnitName, c1.C_Name_History as ecfContractorNameHistory, c2.C_Name_History as ecfSupervisorNameHistory, c1.C_Abbreviation as ecfContractorAbbName, c2.C_Abbreviation as ecfSupervisorAbbName, c3.C_Abbreviation as ecfApplyUnitAbbName, con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal, mn.* from Con_EC_Fee mn left join SYS_Company c1 on mn.Ecf_Contractor=c1.C_Id left join SYS_Company c2 on mn.Ecf_Supervisor=c2.C_Id left join SYS_Company c3 on mn.Ecf_Apply_Unit=c3.C_Id left join Con_Contract con on con.Con_Id=mn.Con_Id
${params.authSql} and mn.Ecf_Type='02'
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Ecf_Create_Time DESC

select c1.C_Name as ecfContractorName, c2.C_Name as ecfSupervisorName, c3.C_Name as ecfApplyUnitName, c1.C_Name_History as ecfContractorNameHistory, c2.C_Name_History as ecfSupervisorNameHistory, c1.C_Abbreviation as ecfContractorAbbName, c2.C_Abbreviation as ecfSupervisorAbbName, c3.C_Abbreviation as ecfApplyUnitAbbName, con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal, ce.Ec_Code as ecCode, ce.Ec_Construction_Name as ecConstructionName, ce.ec_Apply_Money as ecApplyMoney, ce.ec_Change_Type as ecChangeType, ce.ec_Reason as ecReason, ce.ec_Grade as ecGrade, dco.Dco_Name as dcoName, dco.Dco_Code as dcoCode, dco.Dco_Project_Name as dcoProjectName, dco.Dco_Major as dcoMajor, dco.Dco_Sub_Code as dcoSubCode, prect.p_Name as pName, mn.* from Con_EC_Fee mn left join SYS_Company c1 on mn.Ecf_Contractor=c1.C_Id left join SYS_Company c2 on mn.Ecf_Supervisor=c2.C_Id left join SYS_Company c3 on mn.Ecf_Apply_Unit=c3.C_Id left join Con_EC ce on ce.Ec_Id=mn.Ec_Id left join Con_Contract con on con.Con_Id=mn.Con_Id left join Pre_Project prect on prect.P_ID=mn.p_Id left join Con_Dco dco on dco.Dco_Id=mn.Dco_Id
${params.authSql}
where 1=1
and mn.Ecf_Type='03'
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Ecf_Create_Time DESC

select c1.C_Name as ecfContractorName, c2.C_Name as ecfSupervisorName, c3.C_Name as ecfApplyUnitName, c4.C_Name as conPartyBName, c1.C_Name_History as ecfContractorNameHistory, c2.C_Name_History as ecfSupervisorNameHistory, c1.C_Abbreviation as ecfContractorAbbName, c2.C_Abbreviation as ecfSupervisorAbbName, c3.C_Abbreviation as ecfApplyUnitAbbName, con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal, ce.Ec_Code as ecCode, ce.Ec_Apply_Money as ecApplyMoney, con.Con_Project_Id as pId, dco.Dco_Name as dcoName, dco.Dco_Code as dcoCode, dco.Dco_Project_Name as dcoProjectName, dco.Dco_Major as dcoMajor,
mn.* from Con_EC_Fee mn left join SYS_Company c1 on mn.Ecf_Contractor=c1.C_Id left join SYS_Company c2 on mn.Ecf_Supervisor=c2.C_Id left join SYS_Company c3 on mn.Ecf_Apply_Unit=c3.C_Id left join Con_EC ce on ce.Ec_Id=mn.Ec_Id left join Con_Contract con on con.Con_Id=mn.Con_Id left join Con_Dco dco on dco.Dco_Id=mn.Dco_Id left join SYS_Company c4 on con.Con_Party_B_Id=c4.C_Id left join Pre_Project pro on con.Con_Project_Id=pro.P_ID
${params.authSql} and mn.Ecf_Type='01'
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Ecf_Create_Time DESC
